import{_ as p,a0 as l,w as o,s as d,I as n,x as a,a1 as e,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"git stash 命令实用指南 | LCTT x X-CMD","titleTemplate":false,"description":"git stash 命令实用指南 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"git stash 命令实用指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"git stash 命令实用指南 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210402 A practical guide to using the git stash command","title":"git stash 命令实用指南","tag":"202104","desc":""},"relativePath":"202104/20210402 A practical guide to using the git stash command.md","filePath":"[post].md"}'),r={name:"202104/20210402 A practical guide to using the git stash command.md"};function h(g,s,u,k,b,f){const t=l("Link");return o(),d("div",null,[s[23]||(s[23]=n("h1",{id:"git-stash-命令实用指南",tabindex:"-1"},[a("git stash 命令实用指南 "),n("a",{class:"header-anchor",href:"#git-stash-命令实用指南","aria-label":"Permalink to “git stash 命令实用指南”"},"​")],-1)),s[24]||(s[24]=n("blockquote",null,[n("p",null,[a("学习如何使用 "),n("code",null,"git stash"),a(" 命令，以及何时应该使用它。")])],-1)),s[25]||(s[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/12/232830chuyr6lkzevrfuzr.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("版本控制是软件开发人员日常生活中不可分割的一部分。很难想象有哪个团队在开发软件时不使用版本控制工具。同样也很难想象有哪个开发者没有使用过（或没有听说过）Git。在 2018 年 Stackoverflow 开发者调查中，74298 名参与者中有 87.2% 的人 ",-1)),e(t,{href:"https://insights.stackoverflow.com/survey/2018#work-_-version-control"},{default:i(()=>[...s[0]||(s[0]=[a("使用 Git",-1)])]),_:1}),s[2]||(s[2]=a(" 进行版本控制。",-1))]),n("p",null,[s[4]||(s[4]=a("Linus Torvalds 在 2005 年创建了 Git 用于开发 Linux 内核。本文将介绍 ",-1)),s[5]||(s[5]=n("code",null,"git stash",-1)),s[6]||(s[6]=a(" 命令，并探讨一些有用的暂存变更的选项。本文假定你对 ",-1)),e(t,{href:"https://opensource.com/downloads/cheat-sheet-git"},{default:i(()=>[...s[3]||(s[3]=[a("Git 概念",-1)])]),_:1}),s[7]||(s[7]=a(" 有基本的了解，并对工作树、暂存区和相关命令有良好的理解。",-1))]),s[26]||(s[26]=c(`<h3 id="为什么-git-stash-很重要" tabindex="-1">为什么 git stash 很重要？ <a class="header-anchor" href="#为什么-git-stash-很重要" aria-label="Permalink to “为什么 git stash 很重要？”">​</a></h3><p>首先要明白为什么在 Git 中暂存变更很重要。假设 Git 没有暂存变更的命令。当你正在一个有两个分支（A 和 B）的仓库上工作时，这两个分支已经分叉了一段时间，并且有不同的头。当你正在处理 A 分支的一些文件时，你的团队要求你修复 B 分支的一个错误。你迅速将你的修改保存到 A 分支（但没有提交），并尝试用 <code>git checkout B</code> 来签出 B 分支。Git 会立即中止了这个操作，并抛出错误：“你对以下文件的本地修改会被该签出覆盖……请在切换分支之前提交你的修改或将它们暂存起来。”</p><p>在这种情况下，有几种方法可以启用分支切换：</p><ul><li>在分支 A 中创建一个提交，提交并推送你的修改，以修复 B 中的错误，然后再次签出 A，并运行 <code>git reset HEAD^</code> 来恢复你的修改。</li><li>手动保留不被 Git 跟踪的文件中的改动。</li></ul><p>第二种方法是个馊主意。第一种方法虽然看起来很传统，但却不太灵活，因为保存未完成工作的修改会被当作一个检查点，而不是一个仍在进行中的补丁。这正是设计 <code>git stash</code> 的场景。</p><p><code>git stash</code> 将未提交的改动保存在本地，让你可以进行修改、切换分支以及其他 Git 操作。然后，当你需要的时候，你可以重新应用这些存储的改动。暂存是本地范围的，不会被 <code>git push</code> 推送到远程。</p><h3 id="如何使用-git-stash" tabindex="-1">如何使用 git stash <a class="header-anchor" href="#如何使用-git-stash" aria-label="Permalink to “如何使用 git stash”">​</a></h3><p>下面是使用 <code>git stash</code> 时要遵循的顺序：</p><ol><li>将修改保存到分支 A。</li><li>运行 <code>git stash</code>。</li><li>签出分支 B。</li><li>修正 B 分支的错误。</li><li>提交并（可选）推送到远程。</li><li>查看分支 A</li><li>运行 <code>git stash pop</code> 来取回你的暂存的改动。</li></ol><p><code>git stash</code> 将你对工作目录的修改存储在本地（在你的项目的 <code>.git</code> 目录内，准确的说是 <code>/.git/refs/stash</code>），并允许你在需要时检索这些修改。当你需要在不同的上下文之间切换时，它很方便。它允许你保存以后可能需要的更改，是让你的工作目录干净同时保持更改完整的最快方法。</p><h3 id="如何创建一个暂存" tabindex="-1">如何创建一个暂存 <a class="header-anchor" href="#如何创建一个暂存" aria-label="Permalink to “如何创建一个暂存”">​</a></h3><p>暂存你的变化的最简单的命令是 <code>git stash</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash</span></span>
<span class="line"><span>Saved working directory and index state WIP on master; d7435644 Feat: configure graphql endpoint</span></span></code></pre></div><p>默认情况下，<code>git stash</code> 存储（或称之为“暂存”）未提交的更改（已暂存和未暂存的文件），并忽略未跟踪和忽略的文件。通常情况下，你不需要暂存未跟踪和忽略的文件，但有时它们可能会干扰你在代码库中要做的其他事情。</p><p>你可以使用附加选项让 <code>git stash</code> 来处理未跟踪和忽略的文件：</p><ul><li><code>git stash -u</code> 或 <code>git stash --includ-untracked</code> 储存未追踪的文件。</li><li><code>git stash -a</code> 或 <code>git stash --all</code> 储存未跟踪的文件和忽略的文件。</li></ul><p>要存储特定的文件，你可以使用 <code>git stash -p</code> 或 <code>git stash -patch</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash --patch</span></span>
<span class="line"><span>diff --git a/.gitignore b/.gitignore</span></span>
<span class="line"><span>index 32174593..8d81be6e 100644</span></span>
<span class="line"><span>--- a/.gitignore</span></span>
<span class="line"><span>+++ b/.gitignore</span></span>
<span class="line"><span>@@ -3,6 +3,7 @@</span></span>
<span class="line"><span> # dependencies</span></span>
<span class="line"><span> node_modules/</span></span>
<span class="line"><span> /.pnp</span></span>
<span class="line"><span>+f,fmfm</span></span>
<span class="line"><span> .pnp.js</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # testing</span></span>
<span class="line"><span>(1/1) Stash this hunk [y,n,q,a,d,e,?]?</span></span></code></pre></div><h3 id="列出你的暂存" tabindex="-1">列出你的暂存 <a class="header-anchor" href="#列出你的暂存" aria-label="Permalink to “列出你的暂存”">​</a></h3><p>你可以用 <code>git stash list</code> 命令查看你的暂存。暂存是后进先出（LIFO）方式保存的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash list</span></span>
<span class="line"><span>stash@{0}: WIP on master: d7435644 Feat: configure graphql endpoint</span></span></code></pre></div><p>默认情况下，暂存会显示在你创建它的分支和提交的顶部，被标记为 <code>WIP</code>。然而，当你有多个暂存时，这种有限的信息量并没有帮助，因为很难记住或单独检查它们的内容。要为暂存添加描述，可以使用命令 <code>git stash save &lt;description&gt;</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash save &quot;remove semi-colon from schema&quot;</span></span>
<span class="line"><span>Saved working directory and index state On master: remove semi-colon from schema</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git stash list</span></span>
<span class="line"><span>stash@{0}: On master: remove semi-colon from schema</span></span>
<span class="line"><span>stash@{1}: WIP on master: d7435644 Feat: configure graphql endpoint</span></span></code></pre></div><h3 id="检索暂存起来的变化" tabindex="-1">检索暂存起来的变化 <a class="header-anchor" href="#检索暂存起来的变化" aria-label="Permalink to “检索暂存起来的变化”">​</a></h3><p>你可以用 <code>git stash apply</code> 和 <code>git stash pop</code> 这两个命令来重新应用暂存的变更。这两个命令都会重新应用最新的暂存（即 <code>stash@{0}</code>）中的改动。<code>apply</code> 会重新应用变更；而 <code>pop</code> 则会将暂存的变更重新应用到工作副本中，并从暂存中删除。如果你不需要再次重新应用被暂存的更改，则首选 <code>pop</code>。</p><p>你可以通过传递标识符作为最后一个参数来选择你想要弹出或应用的储藏：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash pop stash@{1}</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash apply stash@{1}</span></span></code></pre></div><h3 id="清理暂存" tabindex="-1">清理暂存 <a class="header-anchor" href="#清理暂存" aria-label="Permalink to “清理暂存”">​</a></h3><p>删除不再需要的暂存是好的习惯。你必须用以下命令手动完成：</p><ul><li><code>git stash clear</code> 通过删除所有的暂存库来清空该列表。</li><li><code>git stash drop &lt;stash_id&gt;</code> 从暂存列表中删除一个特定的暂存。</li></ul><h3 id="检查暂存的差异" tabindex="-1">检查暂存的差异 <a class="header-anchor" href="#检查暂存的差异" aria-label="Permalink to “检查暂存的差异”">​</a></h3><p>命令 <code>git stash show &lt;stash_id&gt;</code> 允许你查看一个暂存的差异：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash show stash@{1}</span></span>
<span class="line"><span>console/console-init/ui/.graphqlrc.yml        |   4 +-</span></span>
<span class="line"><span>console/console-init/ui/generated-frontend.ts | 742 +++++++++---------</span></span>
<span class="line"><span>console/console-init/ui/package.json          |   2 +-</span></span></code></pre></div><p>要获得更详细的差异，需要传递 <code>--patch</code> 或 <code>-p</code> 标志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash show stash@{0} --patch</span></span>
<span class="line"><span>diff --git a/console/console-init/ui/package.json b/console/console-init/ui/package.json</span></span>
<span class="line"><span>index 755912b97..5b5af1bd6 100644</span></span>
<span class="line"><span>--- a/console/console-init/ui/package.json</span></span>
<span class="line"><span>+++ b/console/console-init/ui/package.json</span></span>
<span class="line"><span>@@ -1,5 +1,5 @@</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>- &quot;name&quot;: &quot;my-usepatternfly&quot;,</span></span>
<span class="line"><span>+ &quot;name&quot;: &quot;my-usepatternfly-2&quot;,</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;0.1.0&quot;,</span></span>
<span class="line"><span>  &quot;private&quot;: true,</span></span>
<span class="line"><span>  &quot;proxy&quot;: &quot;http://localhost:4000&quot;</span></span>
<span class="line"><span>diff --git a/console/console-init/ui/src/AppNavHeader.tsx b/console/console-init/ui/src/AppNavHeader.tsx</span></span>
<span class="line"><span>index a4764d2f3..da72b7e2b 100644</span></span>
<span class="line"><span>--- a/console/console-init/ui/src/AppNavHeader.tsx</span></span>
<span class="line"><span>+++ b/console/console-init/ui/src/AppNavHeader.tsx</span></span>
<span class="line"><span>@@ -9,8 +9,8 @@ import { css } from &quot;@patternfly/react-styles&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>interface IAppNavHeaderProps extends PageHeaderProps {</span></span>
<span class="line"><span>- toolbar?: React.ReactNode;</span></span>
<span class="line"><span>- avatar?: React.ReactNode;</span></span>
<span class="line"><span>+ toolbar?: React.ReactNode;</span></span>
<span class="line"><span>+ avatar?: React.ReactNode;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export class AppNavHeader extends React.Component&amp;lt;IAppNavHeaderProps&amp;gt;{</span></span>
<span class="line"><span>  render()</span></span></code></pre></div><h3 id="签出到新的分支" tabindex="-1">签出到新的分支 <a class="header-anchor" href="#签出到新的分支" aria-label="Permalink to “签出到新的分支”">​</a></h3><p>你可能会遇到这样的情况：一个分支和你的暂存中的变更有分歧，当你试图重新应用暂存时，会造成冲突。一个简单的解决方法是使用 <code>git stash branch &lt;new_branch_name stash_id&gt;</code> 命令，它将根据创建暂存时的提交创建一个新分支，并将暂存中的修改弹出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash branch test_2 stash@{0}</span></span>
<span class="line"><span>Switched to a new branch &#39;test_2&#39;</span></span>
<span class="line"><span>On branch test_2</span></span>
<span class="line"><span>Changes not staged for commit:</span></span>
<span class="line"><span>(use &quot;git add &lt;file&gt;...&quot; to update what will be committed)</span></span>
<span class="line"><span>(use &quot;git restore &lt;file&gt;...&quot; to discard changes in working directory)</span></span>
<span class="line"><span>modified: .graphqlrc.yml</span></span>
<span class="line"><span>modified: generated-frontend.ts</span></span>
<span class="line"><span>modified: package.json</span></span>
<span class="line"><span>no changes added to commit (use &quot;git add&quot; and/or &quot;git commit -a&quot;)</span></span>
<span class="line"><span>Dropped stash@{0} (fe4bf8f79175b8fbd3df3c4558249834ecb75cd1)</span></span></code></pre></div><h3 id="在不打扰暂存参考日志的情况下进行暂存" tabindex="-1">在不打扰暂存参考日志的情况下进行暂存 <a class="header-anchor" href="#在不打扰暂存参考日志的情况下进行暂存" aria-label="Permalink to “在不打扰暂存参考日志的情况下进行暂存”">​</a></h3><p>在极少数情况下，你可能需要创建一个暂存，同时保持暂存参考日志（<code>reflog</code>）的完整性。这些情况可能出现在你需要一个脚本作为一个实现细节来暂存的时候。这可以通过 <code>git stash create</code> 命令来实现；它创建了一个暂存条目，并返回它的对象名，而不将其推送到暂存参考日志中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash create &quot;sample stash&quot;</span></span>
<span class="line"><span>63a711cd3c7f8047662007490723e26ae9d4acf9</span></span></code></pre></div><p>有时，你可能会决定将通过 <code>git stash create</code> 创建的暂存条目推送到暂存参考日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stash store -m &quot;sample stash testing..&quot; &quot;63a711cd3c7f8047662007490723e26ae9d4acf9&quot;</span></span>
<span class="line"><span>$ git stash list</span></span>
<span class="line"><span>stash @{0}: sample stash testing..</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我希望你觉得这篇文章很有用，并学到了新的东西。如果我遗漏了任何有用的使用暂存的选项，请在评论中告诉我。</p><hr>`,48)),n("p",null,[s[9]||(s[9]=a("via: ",-1)),e(t,{href:"https://opensource.com/article/21/4/git-stash"},{default:i(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/21/4/git-stash",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),e(t,{href:"https://opensource.com/users/rkpattnaik780"},{default:i(()=>[...s[10]||(s[10]=[a("Ramakrishna Pattnaik",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const v=p(r,[["render",h]]);export{x as __pageData,v as default};
